targets.query:
from(bucket: "${bucket}")
  |> range(
      start: v.timeRangeStart,
      stop: v.timeRangeStop
  )

  |> filter(fn: (r) =>
      r["_measurement"] == "${meas}"
  )

  // Dashboard filters
  |> filter(fn: (r) =>
      r["return_code"] =~ /^${return_code:regex}$/
  )

  |> filter(fn: (r) =>
      r["serialboard_id"] =~ /^${sb_id:regex}$/
  )

  |> filter(fn: (r) =>
      r["protectboard_id"] =~ /^${pb_id:regex}$/
  )

  |> filter(fn: (r) =>
      r["qrcode"] =~ /^${qrcode:regex}$/
  )

  |> filter(fn: (r) =>
      r["storehouse_id"] =~ /^${rack_id:regex}$/
  )

  // Left / Right
  |> filter(fn: (r) =>
      r["pallet_position"] == "L" or
      r["pallet_position"] == "R"
  )

  // Only required tags
  |> keep(columns: [
      "serialboard_id",
      "storehouse_id",
      "pallet_position"
  ])

  // Remove duplicate location combinations
  |> group(columns: [
      "serialboard_id",
      "storehouse_id",
      "pallet_position"
  ])
  |> limit(n: 1)

  // Combine locations for each SerialBoard
  |> group(columns: ["serialboard_id"])

  |> reduce(
      identity: {
          locations: ""
      },
      fn: (r, accumulator) => ({
          locations:
              accumulator.locations +
              (
                  if accumulator.locations == "" then ""
                  else " | "
              ) +
              "R" + r.storehouse_id + "_" +
              (
                  if r.pallet_position == "L" then "L"
                  else "R"
              )
      })
  )

  // Grafana Stat output
  |> map(fn: (r) => ({
      _field: r.serialboard_id,
      _value: r.locations
  }))

  |> group()
